// MinimockExecutePushedAuthorizationInspect logs each unmet expectation
func (m *FederationClientMock) MinimockExecutePushedAuthorizationInspect() {
	for _, e := range m.ExecutePushedAuthorizationMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to FederationClientMock.ExecutePushedAuthorization at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterExecutePushedAuthorizationCounter := mm_atomic.LoadUint64(&m.afterExecutePushedAuthorizationCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.ExecutePushedAuthorizationMock.defaultExpectation != nil && afterExecutePushedAuthorizationCounter < 1 {
		if m.ExecutePushedAuthorizationMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to FederationClientMock.ExecutePushedAuthorization at\n%s", m.ExecutePushedAuthorizationMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to FederationClientMock.ExecutePushedAuthorization at\n%s with params: %#v", m.ExecutePushedAuthorizationMock.defaultExpectation.expectationOrigins.origin, *m.ExecutePushedAuthorizationMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcExecutePushedAuthorization != nil && afterExecutePushedAuthorizationCounter < 1 {
		m.t.Errorf("Expected call to FederationClientMock.ExecutePushedAuthorization at\n%s", m.funcExecutePushedAuthorizationOrigin)
	}

	if !m.ExecutePushedAuthorizationMock.invocationsDone() && afterExecutePushedAuthorizationCounter > 0 {
		m.t.Errorf("Expected %d calls to FederationClientMock.ExecutePushedAuthorization at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.ExecutePushedAuthorizationMock.expectedInvocations), m.ExecutePushedAuthorizationMock.expectedInvocationsOrigin, afterExecutePushedAuthorizationCounter)
	}
}

